<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total_size;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       /* 升级包总大小 */</span></span>
